package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcAssessmentPoliciesTest extends JdbcCouponInventoryTest {
 AssessmentPolicies policies;
 @BeforeEach void assessment(){jdbc.execute("DROP TRIGGER IF EXISTS fail_assessment_audit");jdbc.update("DELETE FROM assessment_policy");jdbc.update("DELETE FROM assessment");jdbc.update("UPDATE operator_account SET can_assessment=1 WHERE id=1");policies=new AssessmentPolicies(db,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())));}
 Instant month(int offset){return clock.value.atZone(ZoneId.of("Asia/Shanghai")).withDayOfMonth(1).toLocalDate().plusMonths(offset).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant();}
 ObjectNode config(long merchant){var b=json.createObjectNode().put("merchant_id",merchant).put("acquisition_target",10).put("coupon_target",20).put("source_note","合成测试目标与等级来源").put("valid_from",month(1).toString()).put("valid_to",month(3).toString());b.putArray("process_requirements").add("CHECK_IN_CONFIRMED").add("QUALITY_SIGNED");b.putArray("grade_thresholds").add(json.createObjectNode().put("code","A").put("label","合成高档").put("min_score","80.00")).add(json.createObjectNode().put("code","B").put("label","合成基础档").put("min_score","0.00"));return b;}
 long policy(long merchant){var b=config(merchant);AssessmentPolicyInput.body(b.toString(),false);return policies.create(operator,key(),b).path("data").path("id").asLong();}
 void activate(long id){policies.status(operator,id,key(),statusBody(1,"PUBLISHED"));}
 @Test void unknownPolicyNeverImportsLegacyDefaultScoresOrCalculates(){assertEquals("UNKNOWN",policies.current(merchant).get("state"));assertEquals(true,policies.current(merchant).get("scoring_available"));jdbc.update("INSERT INTO assessment(merchant_id,period_month,total_score,grade) VALUES(1,CURRENT_DATE,99,'LEGACY')");long p=policy(1);activate(p);var current=policies.current(merchant);assertEquals("NOT_STARTED",current.get("state"));assertEquals(true,current.get("scoring_available"));assertFalse(db.json(current).contains("LEGACY"));assertEquals(new java.math.BigDecimal("99.00"),jdbc.queryForObject("SELECT total_score FROM assessment",java.math.BigDecimal.class));assertEquals(0,count("coupon_issue"));assertEquals(0,count("point_verified_entry"));}
 @Test void onlyIndependentPermissionWorksAndReplayAlwaysReauthorizes(){jdbc.update("UPDATE operator_account SET can_assessment=0,can_points=1,can_coupon=1,can_invite=1 WHERE id=1");assertEquals(403,code(()->policies.list(operator,1)));assertEquals(403,code(()->policies.merchants(operator,1)));assertEquals(403,code(()->policies.create(operator,key(),config(1))));jdbc.update("UPDATE operator_account SET can_assessment=1 WHERE id=1");String k=key();var b=config(1);policies.create(operator,k,b);jdbc.update("UPDATE operator_account SET can_assessment=0 WHERE id=1");assertEquals(403,code(()->policies.create(operator,k,b)));}
 @Test void realMerchantScopeAndCurrentManagerDoNotPermitOtherStoreOrStaff(){long p=policy(1);activate(p);assertEquals("UNKNOWN",policies.current(other).get("state"));assertEquals(2L,policies.merchants(operator,1).get("total"));jdbc.update("UPDATE merchant SET status=0 WHERE id=2");assertEquals(404,code(()->policy(2)));assertEquals(1L,policies.merchants(operator,1).get("total"));var staff=new com.autocare.platform.service.MerchantActor(1,1,"STAFF",merchant.session(),merchant.expires());assertEquals(403,code(()->policies.current(staff)));}
 @Test void draftCasFreezeStopAndOnePublishedPerMerchant(){long p=policy(1);var b=config(1).put("expected_revision",1).put("coupon_target",22);policies.update(operator,p,key(),b);assertEquals(409,code(()->policies.update(operator,p,key(),b)));policies.status(operator,p,key(),statusBody(2,"PUBLISHED"));assertEquals(409,code(()->policies.update(operator,p,key(),b.put("expected_revision",3))));long replacement=policy(1);assertEquals(409,code(()->activate(replacement)));activate(policy(2));policies.status(operator,p,key(),statusBody(3,"STOPPED"));activate(replacement);assertEquals(409,code(()->policies.status(operator,p,key(),statusBody(4,"PUBLISHED"))));assertFalse(db.json(policies.list(operator,1)).contains("submission_hash"));}
 @Test void futureWholeBeijingMonthsAndExclusiveEndAreRequired(){assertEquals(409,code(()->policies.create(operator,key(),config(1).put("valid_from",month(0).toString()))));assertThrows(Exception.class,()->AssessmentPolicyInput.body(config(1).put("valid_from",month(1).plusSeconds(1).toString()).toString(),false));long p=policy(1);activate(p);clock.value=month(1);assertEquals("CONFIGURED",policies.current(merchant).get("state"));clock.value=ReservationStore.instant(policies.row(p,false).get("valid_to"));assertEquals("EXPIRED",policies.current(merchant).get("state"));}
 @Test void publicationRechecksTimeAndMerchantAfterDraftAndStopStillWorks(){long p=policy(1);jdbc.update("UPDATE merchant SET status=0 WHERE id=1");assertEquals(404,code(()->activate(p)));jdbc.update("UPDATE merchant SET status=1 WHERE id=1");activate(p);jdbc.update("UPDATE merchant SET status=0 WHERE id=1");policies.status(operator,p,key(),statusBody(2,"STOPPED"));assertEquals("STOPPED",policies.row(p,false).get("status"));}
 @Test void permanentReceiptUsesCanonicalNestedFieldsAndSurvivesWindowAndStatusChanges(){String k=key();var b=config(1);var first=policies.create(operator,k,b);long p=first.path("data").path("id").asLong();activate(p);clock.value=month(4);jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");var reordered=b.deepCopy();var g=(ObjectNode)reordered.path("grade_thresholds").get(0);var same=json.createObjectNode().put("min_score",g.path("min_score").asText()).put("label",g.path("label").asText()).put("code",g.path("code").asText());((com.fasterxml.jackson.databind.node.ArrayNode)reordered.get("grade_thresholds")).set(0,same);assertEquals(first.path("data"),policies.create(operator,k,reordered).path("data"));assertEquals(1,count("assessment_policy"));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(400,code(()->policies.create(operator,k,b.deepCopy().put("coupon_target",21))));}
 @Test void auditFailureRollsBackDraftAndPublication(){jdbc.execute("CREATE TRIGGER fail_assessment_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");String k=key();assertEquals(503,code(()->policies.create(operator,k,config(1))));assertEquals(0,count("assessment_policy"));jdbc.execute("DROP TRIGGER fail_assessment_audit");long p=policies.create(operator,k,config(1)).path("data").path("id").asLong();jdbc.execute("CREATE TRIGGER fail_assessment_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->activate(p)));assertEquals("DRAFT",policies.row(p,false).get("status"));}
 @Test void differentOperatorsCannotPublishTwoPoliciesForSameMerchant()throws Exception{long a=policy(1),b=policy(1);jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_assessment) VALUES(2,'assessment-peer','unused','13800000001',1)");var otherOp=new OperatorActor(2,session(2,"operator_account","OPERATOR",OperatorActor.APP,null),Instant.now().plusSeconds(600));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var first=pool.submit(()->{start.await();try{activate(a);return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var second=pool.submit(()->{start.await();try{policies.status(otherOp,b,key(),statusBody(1,"PUBLISHED"));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});start.countDown();var codes=new ArrayList<>(List.of(first.get(30,TimeUnit.SECONDS),second.get(30,TimeUnit.SECONDS)));Collections.sort(codes);assertEquals(List.of(200,409),codes);}finally{pool.shutdownNow();}}
 @Test void strictTargetsEvidenceGradesAndFixedWeightsAreValidated(){var b=config(1);for(String raw:List.of(b.deepCopy().put("weights",40).toString(),b.deepCopy().put("acquisition_target",0).toString(),b.deepCopy().put("coupon_target",1.5).toString(),b.deepCopy().put("source_note"," x ").toString(),b.deepCopy().put("valid_to",month(1).toString()).toString(),b+"{}"))assertThrows(Exception.class,()->AssessmentPolicyInput.body(raw,false));var missing=config(1);missing.putArray("process_requirements");assertThrows(Exception.class,()->AssessmentPolicyInput.body(missing.toString(),false));var duplicate=config(1);duplicate.withArray("process_requirements").add("QUALITY_SIGNED");assertThrows(Exception.class,()->AssessmentPolicyInput.body(duplicate.toString(),false));var invalid=config(1);((ObjectNode)invalid.withArray("grade_thresholds").get(1)).put("min_score","0.01");assertThrows(Exception.class,()->AssessmentPolicyInput.body(invalid.toString(),false));assertThrows(Exception.class,()->policies.list(operator,0));}
}
